function createBaseWallpaperContent(): WallpaperContent {
  return {
    roomId: "0",
    channelId: "0",
    wallpaperId: "0",
    status: 0,
    sendTimestamp: "0",
    playUserId: "0",
    wallpaperUrl: "",
    finishedUserList: [],
    playUserList: [],
  };
}

export const WallpaperContent: MessageFns<WallpaperContent> = {
  encode(message: WallpaperContent, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.roomId !== "0") {
      writer.uint32(8).int64(message.roomId);
    }
    if (message.channelId !== "0") {
      writer.uint32(16).int64(message.channelId);
    }
    if (message.wallpaperId !== "0") {
      writer.uint32(24).int64(message.wallpaperId);
    }
    if (message.status !== 0) {
      writer.uint32(32).int32(message.status);
    }
    if (message.sendTimestamp !== "0") {
      writer.uint32(40).int64(message.sendTimestamp);
    }
    if (message.playUserId !== "0") {
      writer.uint32(48).int64(message.playUserId);
    }
    if (message.wallpaperUrl !== "") {
      writer.uint32(58).string(message.wallpaperUrl);
    }
    for (const v of message.finishedUserList) {
      WallpaperContext.encode(v!, writer.uint32(66).fork()).join();
    }
    for (const v of message.playUserList) {
      WallpaperContext.encode(v!, writer.uint32(74).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): WallpaperContent {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseWallpaperContent();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 8) {
            break;
          }

          message.roomId = reader.int64().toString();
          continue;
        }
        case 2: {
          if (tag !== 16) {
            break;
          }

          message.channelId = reader.int64().toString();
          continue;
        }
        case 3: {
          if (tag !== 24) {
            break;
          }

          message.wallpaperId = reader.int64().toString();
          continue;
        }
        case 4: {
          if (tag !== 32) {
            break;
          }

          message.status = reader.int32();
          continue;
        }
        case 5: {
          if (tag !== 40) {
            break;
          }

          message.sendTimestamp = reader.int64().toString();
          continue;
        }
        case 6: {
          if (tag !== 48) {
            break;
          }

          message.playUserId = reader.int64().toString();
          continue;
        }
        case 7: {
          if (tag !== 58) {
            break;
          }

          message.wallpaperUrl = reader.string();
          continue;
        }
        case 8: {
          if (tag !== 66) {
            break;
          }

          message.finishedUserList.push(WallpaperContext.decode(reader, reader.uint32()));
          continue;
        }
        case 9: {
          if (tag !== 74) {
            break;
          }

          message.playUserList.push(WallpaperContext.decode(reader, reader.uint32()));
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },
};

